async function getMetadata(url) {
    const response = await fetch(url, {
        headers: { 'Icy-MetaData': '1' }
    });

    const interval = Number(response.headers.get('icy-metaint'));

    if (!interval) {
        await response.body.cancel();
        throw new Error('icy-metaint отсутствует или скрыт CORS');
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();

    let skip = interval;
    let size = 0;
    let bytes = [];

    try {
        while (true) {
            const { value, done } = await reader.read();
            if (done) break;

            for (const byte of value) {
                if (skip > 0) {
                    skip--;
                } else if (size === 0) {
                    size = byte * 16;
                    if (!size) skip = interval;
                } else {
                    bytes.push(byte);

                    if (bytes.length === size) {
                        console.log(
                            decoder.decode(new Uint8Array(bytes))
                                .replace(/\0+$/, '')
                        );

                        bytes = [];
                        size = 0;
                        skip = interval;
                    }
                }
            }
        }
    } finally {
        await reader.cancel();
    }
}


